      function rankMeta(source,r){var lr=null,i;if(source.lensRows){for(i=0;i<source.lensRows.length;i++){if(source.lensRows[i].team===r.team){lr=source.lensRows[i];break}}}return r.meta+(lr?' · '+lr.pa+' PA':'')}
      function rankingObjects(source,key,mode){var byTeam={},order=rankOrders[key+'-'+mode]||rankOrders['draft-review'];source.ranks.forEach(function(r){byTeam[r.team]=r});return order.map(function(team){return byTeam[team]||editions.draft.ranks.filter(function(r){return r.team===team})[0]})}
      function movementFor(team,currentKey){var previous=rankOrders[rankPrevious[currentKey]],current=rankOrders[currentKey],from=previous.indexOf(team)+1,to=current.indexOf(team)+1,delta=from-to;return delta>0?'▲ '+delta:delta<0?'▼ '+Math.abs(delta):'— 0'}
      function powerBoard(source,key,heading,mode){var currentKey=key+'-'+mode,items=rankingObjects(source,key,mode),isDraft=key==='draft',isPreview=mode==='preview';return '<div class="section-head"><h2>'+esc(heading)+'</h2></div><div class="power-board">'+items.map(function(r,i){var move=isDraft||isPreview?'':movementFor(r.team,currentKey);return '<div class="power-row '+(i<2?'top':'')+'"><span class="power-rank">'+(i+1)+'</span><div class="power-team"><strong>'+esc(r.team)+'</strong><span>'+esc(rankMeta(source,r))+'</span></div><div class="power-case">'+esc(r.case)+'</div>'+(!isDraft&&!isPreview?'<span class="power-tag movement '+movementClass(move)+'">'+esc(move)+'</span>':'')+'</div>'}).join('')+'</div>'}
