      function renderWaivers(w){return '<div class="wire"><div class="label" style="color:var(--red)">Transaction notes</div><h2>'+esc(w.title)+'</h2><ol class="wire-list">'+w.moves.slice(0,5).map(function(move,i){return '<li><span class="ranknum">'+(i+1)+'</span><div><strong>'+esc(move[0])+'</strong><span>'+esc(move[1])+'</span></div></li>'}).join('')+'</ol><p class="waiver-note">'+esc(w.note)+'</p></div>'}
